print("=== 集群总线 gossip 拓扑传播模拟 ===")
nodes = {
    "A": {"knows": set(["A"])},
    "B": {"knows": set(["B"])},
    "C": {"knows": set(["C"])},
}
print("初始: 每节点只认识自己 -> A:%s B:%s C:%s" % (sorted(nodes["A"]["knows"]), sorted(nodes["B"]["knows"]), sorted(nodes["C"]["knows"])))
import itertools
rounds = 0
while not all(nodes[n]["knows"] == set(["A", "B", "C"]) for n in nodes):
    for a, b in itertools.permutations(nodes, 2):
        nodes[a]["knows"] |= nodes[b]["knows"]
    rounds += 1
    if rounds > 5:
        break
print("经过 %d 轮 gossip PING/PONG 交换:" % rounds)
for n in sorted(nodes):
    print("  %s 已知节点: %s" % (n, sorted(nodes[n]["knows"])))
print("结果: 所有节点对集群视图达成一致 (最终一致)")
